package br.com.loja.product;import jakarta.persistence.*;import java.math.BigDecimal;@Entity @Table(name="products")public class Product{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false,unique=true)private String sku;@Column(nullable=false)private String name;@Column(length=1000)private String description;private String category;@Column(nullable=false,precision=12,scale=2)private BigDecimal price;@Column(nullable=false)private Integer stock;@Column(nullable=false)private boolean active=true;public Product(){}public Product(Long id,String sku,String name,String description,String category,BigDecimal price,Integer stock,boolean active){this.id=id;this.sku=sku;this.name=name;this.description=description;this.category=category;this.price=price;this.stock=stock;this.active=active;}public Long getId(){return id;}public String getSku(){return sku;}public void setSku(String v){sku=v;}public String getName(){return name;}public void setName(String v){name=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public String getCategory(){return category;}public void setCategory(String v){category=v;}public BigDecimal getPrice(){return price;}public void setPrice(BigDecimal v){price=v;}public Integer getStock(){return stock;}public void setStock(Integer v){stock=v;}public boolean isActive(){return active;}public void setActive(boolean v){active=v;}}